        body: `▼ゼロから：
同じ大きさの窓でも、目の前に高い建物が迫っていれば暗いままです。
だから建築基準法は「窓の面積」をそのまま採光面積として認めません。
周囲の状況に応じて割増ししたり割り引いたりする係数を掛けます。
それが採光補正係数です。窓面積に掛け算して有効採光面積を出します。
法規科目とも重なりますが、計算の型は建築計画でも問われます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 有効採光面積の基本式
━━━━━━━━━━━━━━━━━━━━━━
・有効採光面積 ＝ 窓の面積 × 採光補正係数★
・居室の床面積に対して必要な有効採光面積の割合が用途ごとに定められる
・住宅の居室：床面積の7分の1以上★
・小学校・中学校・高等学校の教室：床面積の5分の1以上★
・保育所の保育室・幼稚園の教室：床面積の5分の1以上
・病院・診療所の病室、寄宿舎の寝室：床面積の7分の1以上
・事務室・会議室には採光の義務がない（換気は必要）★

【計算例】住宅の居室に必要な窓面積
　条件：居室の床面積20平方メートル、採光補正係数1.0
　必要有効採光面積 ＝ 20 × 1 ÷ 7 ＝ 約2.86平方メートル
　窓面積 ＝ 必要有効採光面積 ÷ 採光補正係数 ＝ 2.86 ÷ 1.0
　答え：約2.86平方メートル以上の窓が必要
　→ 補正係数が0.5なら必要窓面積は倍の約5.72平方メートルになる

━━━━━━━━━━━━━━━━━━━━━━
🔑 採光補正係数の求め方
━━━━━━━━━━━━━━━━━━━━━━
・まず採光関係比率 ＝ 水平距離D ÷ 垂直距離H を求める★
・Dは窓の面から隣地境界線や向かいの建物までの水平距離
・Hは窓の中心から、その建築物の直上の軒等までの垂直距離
・用途地域ごとに係数と定数が異なる（住居系・工業系・商業系）
・住居系：D÷H × 6 － 1.4★
・工業系：D÷H × 8 － 1.0★
・商業系（近隣商業・商業・用途地域無指定）：D÷H × 10 － 1.0★
・算定値が3.0を超える場合は3.0とする（上限）★
・算定値が負になる場合は0とする

【図解】用途地域別の採光補正係数の算定式
　地域区分｜算定式｜覚え方
　住居系｜D÷H×6－1.4★｜6と1.4
　工業系｜D÷H×8－1.0★｜8と1.0
　商業系｜D÷H×10－1.0★｜10と1.0
　→ 商業系ほど密集を前提に有利な係数となっている
　⚠「住居系の定数は1.0」は誤り。住居系だけ1.4である★

【計算例】住居系地域での採光補正係数
　条件：水平距離D＝4メートル、垂直距離H＝8メートル、第一種住居地域
　採光関係比率 ＝ 4 ÷ 8 ＝ 0.5
　式：0.5 × 6 － 1.4
　代入：3.0 － 1.4
　答え：採光補正係数 ＝ 1.6
　窓面積が3平方メートルなら有効採光面積 ＝ 3 × 1.6 ＝ 4.8平方メートル

━━━━━━━━━━━━━━━━━━━━━━
🔑 特例と実務上の注意
━━━━━━━━━━━━━━━━━━━━━━
・天窓（水平の窓）は算定値を3倍する★
・縁側等（幅90センチメートル以上）を通して採光する場合は0.7を乗じる★
・ふすま・障子など随時開放できるもので仕切られた2室は1室とみなせる★
・道に面する窓は、算定値が1.0未満でも1.0とすることができる
・隣地境界線までの距離が一定以上ある場合も1.0を下限とする救済がある

【図解】採光補正係数の割増と割減
　条件｜扱い｜倍率
　天窓｜3倍する★｜×3.0
　幅90センチ以上の縁側越し｜0.7倍する★｜×0.7
　算定値が3.0超｜上限を適用｜3.0とする
　⚠「天窓は2倍」は誤り。3倍である★

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・×「住宅の居室の採光は床面積の5分の1以上」→ 7分の1以上★
・×「事務室にも採光の規定が適用される」→ 適用されない
・×「採光補正係数の上限は5.0」→ 3.0★
・○「天窓の採光補正係数は算定値の3倍」→ 正しい
・○「D÷Hが大きいほど採光補正係数は大きい」→ 正しい
・計算は「D÷Hを出す→式に代入→上限3.0で頭打ち→窓面積に掛ける」の4段階で解く

━━━━━━━━━━━━━━━━━━━━━━
🔑 複数の窓がある場合と算定の実務
━━━━━━━━━━━━━━━━━━━━━━
・居室に複数の開口部があるときは、各窓ごとに補正係数を求めて合算する★
・方位が違えば水平距離Dも垂直距離Hも異なるため、まとめて計算してはいけない★
・開口部のうち、はめ殺し窓も採光には算入できる（換気には算入できない）★
・ドアのガラス部分も、採光上有効な部分は算入できる
・襖や障子で仕切られた2室は1室とみなせるため、奥の室の採光を隣室の窓で確保できる

【計算例】2つの窓をもつ居室
　条件：窓A 2平方メートル×係数1.5、窓B 1.5平方メートル×係数0.8
　窓Aの有効採光面積 ＝ 2 × 1.5 ＝ 3.0平方メートル
　窓Bの有効採光面積 ＝ 1.5 × 0.8 ＝ 1.2平方メートル
　合計 ＝ 3.0 ＋ 1.2 ＝ 4.2平方メートル
　この居室が住宅の居室なら、床面積は 4.2 × 7 ＝ 29.4平方メートルまで許容される

★ここだけ暗記
・有効採光面積＝窓面積×採光補正係数
・住宅7分の1、学校の教室5分の1★
・住居系6と1.4、工業系8と1.0、商業系10と1.0
・上限3.0、天窓3倍、縁側0.7倍`,
