肉が新鮮に見えるか、絵画が本来の色に見えるか。それを決めるのが演色性です。
また、同じ明るさでも青白い光と赤みの光では雰囲気がまるで違う。それが色温度。
そして明るすぎて見えづらくなる現象がグレアです。数値ではなく概念で問われます。

━━━━━━━━━━━━━━━━━━━━━━
