給気にファンを使うか、排気に使うか、両方に使うか。組合せは3通りしかありません。
そしてどれを選ぶかは「その室を周囲より高い気圧にしたいか、低くしたいか」で決まります。
臭いを閉じ込めたい室は負圧、汚れを入れたくない室は正圧。これだけです。

