・全熱交換器は第1種換気でなければ成立しない（給排気を同時に機械で扱うため）★
・外気負荷を大幅に削減でき、ZEB・ZEH計画で標準的に採用される
・フィルターの目詰まりで風量が落ちるため、保守が前提となる

