        title: '結露の判定と防止',
        emoji: '🌫️',
        body: `▼ゼロから：
冷たいビールのグラスに水滴がつくのと、冬の窓が濡れるのは同じ現象です。
空気が冷たいものに触れて露点温度以下になり、水蒸気が水に戻る。それが結露です。
建物では、目に見える表面結露より、壁の中で起こる内部結露のほうが厄介です。
腐朽やカビを引き起こし、断熱性能まで落としてしまうからです。
判定の基準はただ1つ、「その場所の温度が露点温度を下回るかどうか」です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 表面結露の判定原理
━━━━━━━━━━━━━━━━━━━━━━
・室内側表面温度 ＜ 室内空気の露点温度 → 表面結露が発生する★
・逆に表面温度が露点温度より高ければ結露しない★
・したがって対策は2つ。表面温度を上げるか、露点温度を下げるかである★
・表面温度を上げる＝断熱を強化する、暖房する★
・露点温度を下げる＝換気や除湿で室内の水蒸気量を減らす★
・熱橋部・押入れ内部・家具の裏側・北側の部屋の隅は表面温度が低く結露しやすい★
・開放型石油ストーブは燃焼で水蒸気を出すため、結露を助長する★

【計算例】表面結露の判定
　条件：外気0度、室温20度、室内相対湿度60パーセント
　外壁の熱貫流率U＝2.0、室内側熱伝達抵抗0.11
　表面温度 ＝ 室温 － U × 室内側熱伝達抵抗 × 内外温度差
　代入：20 － 2.0 × 0.11 × （20 － 0）
　計算：20 － 4.4
　答え：表面温度 ＝ 15.6度
　室温20度・相対湿度60パーセントの露点温度は約12度
　判定：15.6度 ＞ 12度 なので結露しない★

【計算例】断熱不足の場合
　条件を変え、U＝4.0（単板ガラスに近い）とする
　表面温度 ＝ 20 － 4.0 × 0.11 × 20 ＝ 20 － 8.8 ＝ 11.2度
　判定：11.2度 ＜ 12度 なので結露する★
　→ 同じ室内条件でも、U値が大きいだけで結露に転じる

━━━━━━━━━━━━━━━━━━━━━━
🔑 内部結露のしくみ
━━━━━━━━━━━━━━━━━━━━━━
・水蒸気は水蒸気圧の高いほうから低いほうへ材料を透過して移動する★
・冬は室内の水蒸気圧が高いため、水蒸気は室内から屋外へ向かう★
・壁体内部で温度が露点以下になる位置があると、そこで内部結露が起こる★
・内部結露は目に見えないため発見が遅れ、木材腐朽や断熱材の性能低下を招く★
・判定は、壁体内の各点の温度勾配と水蒸気圧の勾配を比べて行う★
・その点の水蒸気圧が、その点の温度に対する飽和水蒸気圧を超えると結露する★

━━━━━━━━━━━━━━━━━━━━━━
🔑 防湿層と通気層の原則
━━━━━━━━━━━━━━━━━━━━━━
・防湿層は水蒸気の侵入そのものを止める。断熱材の室内側（高温側）に設ける★
・通気層は入ってしまった水蒸気を外へ逃がす。断熱材の屋外側に設ける★
・「室内側は防湿、屋外側は透湿」が鉄則★
・外壁通気構法は、外装材の裏に通気層を設けて湿気と雨水を排出する★
・透湿防水シートは、水は通さず水蒸気は通す。通気層の屋内側に用いる★
・寒冷地では防湿層の連続性がとくに重要。継目はテープで確実に処理する★

【図解】冬型結露に対する層構成の原則
　位置｜設けるもの｜役割
　室内側｜防湿層★｜水蒸気の侵入を止める
　中間｜断熱材｜温度勾配をつくる
　屋外側｜通気層と透湿防水シート★｜湿気を排出する
　⚠「屋外側に防湿層、室内側に通気層」は完全な誤り★

━━━━━━━━━━━━━━━━━━━━━━
🔑 夏型結露と特殊なケース
━━━━━━━━━━━━━━━━━━━━━━
・夏型結露：高温多湿の外気の水蒸気が壁内に入り、冷房で冷えた室内側で結露する★
・夏型では水蒸気の流れが冬と逆になるため、室内側の防湿層が結露面になりうる★
・地下室では、夏に冷たい壁面に室内の湿った空気が触れて結露する★
・鉄筋コンクリート造は熱容量が大きく、夏に躯体が冷えていて結露しやすい
・二重サッシや複層ガラスは表面温度を上げるので表面結露に有効★
・浴室・厨房などの水蒸気発生室は、局所排気で発生源から直接排出する★

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・×「表面温度が露点温度より高いと結露する」→ 低いと結露する★
・×「防湿層は断熱材の屋外側に設ける」→ 室内側★
・×「室内の水蒸気量を増やせば結露を防げる」→ 増やすと露点が上がり悪化★
・×「内部結露は表面結露より発見しやすい」→ 発見しにくく被害が大きい★
・○「熱橋部は表面温度が低く結露しやすい」→ 正しい
・○「複層ガラスは表面結露の防止に有効」→ 正しい
・計算問題は「表面温度＝室温－U×室内側熱伝達抵抗×温度差」と露点の比較で解く★

★ここだけ暗記
・表面温度 ＜ 露点温度 なら結露する★
・表面温度＝室温－U×0.11×内外温度差
・防湿層は室内側、通気層は屋外側★
・対策は断熱強化・換気除湿・局所排気の3方向`,
