　テラスハウス｜各戸ごとに分割★｜専用庭をもつ連続住宅
　タウンハウス｜共有（コモンスペース）★｜共用の庭をもつ
　コートハウス｜各戸に中庭｜壁で囲みプライバシーを確保★
　⚠「タウンハウスは各戸ごとに敷地が分割される」は誤り

