【図解】住戸平面形式の比較
　形式｜南面に取れる室数｜特徴
　田の字型｜2室★｜経済的だが北側居室が不利★
　ワイドスパン型｜3室以上★｜採光通風に優れ戸数は減る★
　センターイン型｜2室程度｜廊下が短く面積効率が良い
　⚠「田の字型は南面に3室を確保できる」は誤り

━━━━━━━━━━━━━━━━━━━━━━
