・厨房排水は間接排水とし、逆流による汚染を防ぐ★
・排気ダクトは不燃材とし、防火ダンパーを設ける★
・飲食店は食品衛生法により営業許可が必要で、手洗い設備の設置が求められる★
・客席部分は原則として禁煙。喫煙専用室を設ける場合は基準を満たす必要がある★

