・在宅介護支援センター・訪問看護ステーション：在宅療養を支える拠点★
・介護老人保健施設（老健）：在宅復帰を目指すリハビリ中心の施設★
・介護老人福祉施設（特別養護老人ホーム）：常時介護が必要な高齢者の生活の場★
・介護医療院：長期療養と生活の場を兼ねる施設★

【図解】保健所と保健センターの違い
　施設｜設置主体｜主な役割
　保健所｜都道府県・政令市等★｜広域的・専門的な公衆衛生★
　市町村保健センター｜市町村★｜住民に身近な健診・相談★
　地域包括支援センター｜市町村（委託可）★｜高齢者の総合相談★
　⚠「市町村保健センターは都道府県が設置する」は誤り

