・人体寸法（身長183センチメートル、手を上げた高さ226センチメートル）を基準とする★
・黄金比とフィボナッチ数列を用いて、寸法系列を組み立てた★
・赤の系列と青の系列の2つの数列からなる★
・マルセイユのユニテ・ダビタシオンなど、彼の作品に適用された★
・美的な調和と機能性の両立を目指した点が特徴★

━━━━━━━━━━━━━━━━━━━━━━
