・廊下等の幅は120センチメートル以上★
・階段は、手すりを設け、踏面の端部と周囲との色の明度差を確保する★
・階段には点状ブロック等を上端に近接する踊場に敷設する★
・傾斜路の勾配は12分の1以下（高さ16センチメートル以下は8分の1以下）★
・車椅子使用者用便房を1以上設ける★
・車椅子使用者用駐車施設を1以上設け、幅350センチメートル以上とする★
・エレベーターのかごは、間口140センチメートル以上、奥行135センチメートル以上★

【図解】主な基準値
　項目｜基準値｜備考
　出入口の有効幅｜80センチメートル以上★｜主要な出入口は90センチメートル以上★
　廊下の幅｜120センチメートル以上★｜通行の確保
　傾斜路の勾配｜12分の1以下★｜高さ16センチメートル以下は8分の1以下★
　⚠「傾斜路の勾配は8分の1以下が原則である」は誤り。12分の1以下が原則★

