━━━━━━━━━━━━━━━━━━━━━━
・建築物移動等円滑化誘導基準は、より高い水準を定めた任意の基準★
・誘導基準に適合すると、所管行政庁の認定（認定特定建築物）を受けられる★
・認定を受けると、容積率の特例や表示（マーク）の使用が認められる★
・誘導基準では、廊下幅180センチメートル以上、出入口90センチメートル以上など★
