・誘導サイン：目的地への方向を示す（矢印と行き先）★
・案内サイン：全体の構成を示す（フロアマップ・館内案内図）★
・記名サイン（位置サイン）：その場所が何かを示す（室名札）★
・規制サイン：禁止・注意を示す（立入禁止・禁煙）★
