それ以前の貴族の住まいは、床が板張りで、間仕切りもありませんでした。
住宅の形は、住む人の身分や暮らし方が変われば変わります。
本節では住宅と城郭の歴史を、変化の順序で押さえます。

━━━━━━━━━━━━━━━━━━━━━━
