・層塔型：各層を同じ形で規則的に積み上げる形式。江戸時代以降★
・層塔型の例は、名古屋城、島原城★
・姫路城は白鷺城とも呼ばれ、連立式天守（大天守と小天守を渡櫓で結ぶ）★
・城の縄張（配置計画）には、輪郭式・連郭式・梯郭式などがある★
・書院造の御殿が城内に建てられ、二条城二の丸御殿が代表例★

━━━━━━━━━━━━━━━━━━━━━━
