・ハギア・ソフィア（イスタンブール）：ペンデンティブドームの代表作★
・内部はモザイクで装飾され、光に満ちた神秘的な空間をつくる★
・サン・ヴィターレ聖堂（ラヴェンナ）も集中式の代表例★

【図解】ドームの架け方
　技法｜内容｜代表例
