・石造のヴォールト（半円筒ヴォールト・交差ヴォールト）で屋根を架ける★
・壁が構造を担うため、開口部が小さく内部は薄暗い★
・重厚で閉鎖的、水平線を強調した外観★
・ピサ大聖堂（イタリア）、サン・セルナン聖堂（フランス）が代表例★
・地方ごとに多様な形式が生まれた

