・12から15世紀。垂直性と大きな開口部が特徴★
・3つの技術要素は、尖頭アーチ・リブヴォールト・フライングバットレス★
・尖頭アーチ（ポインテッドアーチ）：横に広がる力を減らし、高さを自由にできる★
・リブヴォールト：ヴォールトの稜線に骨（リブ）を設け、力の流れを集中させる★
・フライングバットレス（飛梁）：外部の控壁で横力を受け、壁を薄くできる★
・その結果、壁を大きく開口でき、ステンドグラスによる光の空間が生まれた★
・バラ窓（円形のステンドグラス）が正面を飾る★
・ノートルダム大聖堂（パリ）、シャルトル大聖堂、アミアン大聖堂、ケルン大聖堂が代表例★

【図解】ロマネスクとゴシックの比較
