　内部の印象｜重厚で薄暗い★｜垂直的で光に満ちる★
　代表例｜ピサ大聖堂★｜ノートルダム大聖堂★
　⚠「ゴシック建築は半円アーチと厚い壁を特徴とする」は誤り。ロマネスクである★

