・レジオネラ属菌は20度から50度で繁殖しやすい★
・浴用の湯は42度程度、洗面・手洗いは40度程度、厨房は45度程度★
・高温の湯によるやけどを防ぐため、シャワーには湯温調節（サーモスタット）を設ける★
・小児・高齢者施設では、湯温の上限を設定する★
・給湯配管は保温し、熱損失と結露を防ぐ★

━━━━━━━━━━━━━━━━━━━━━━
