　省エネ性｜劣る★｜優れる（搬送動力を削減）★
　換気量｜常に確保★｜低負荷時に不足のおそれ★
　⚠「VAV方式は常に一定の換気量が確保される」は誤り

━━━━━━━━━━━━━━━━━━━━━━
