・ファンコイルユニット（FCU）方式：各室に小型の送風機とコイルを置く★
・冷温水を配管で送り、各室で空気と熱交換する★
・FCUは個別制御性に優れ、ゾーニングが容易★
・FCUは各室に機器があるため、保守点検の手間が大きい★
・FCUだけでは外気を導入できないため、外調機（外気処理空調機）を併用する★
・ペリメーター（外周部）にFCU、インテリア（内部）に単一ダクトという併用が一般的★

【図解】主な空調方式の適用
　方式｜個別制御性｜主な適用
　単一ダクト（CAV）★｜低い★｜大空間・劇場★
　単一ダクト（VAV）★｜中程度★｜一般事務所★
　ファンコイル併用★｜高い★｜ホテル客室・ペリメーター★
　⚠「二重ダクト方式は最も経済的な方式である」は誤り。不経済★

━━━━━━━━━━━━━━━━━━━━━━
