・受変電設備は、高圧を受電して低圧に変換し、建物内に配る設備★
・キュービクル式高圧受電設備は、金属箱に機器を収めたもの★
・屋外キュービクルは、建築物や道路境界から3メートル以上離す★
・変圧器（トランス）は、高圧を低圧に変換する中心機器★
・遮断器・断路器・避雷器・進相コンデンサなどで構成される★
