━━━━━━━━━━━━━━━━━━━━━━
・幹線は、受変電設備から各階の分電盤までを結ぶ主要な電路★
・幹線の設計では、負荷容量・電圧降下・許容電流・短絡電流を検討する★
・電圧降下は、幹線と分岐回路を合わせて標準電圧の2パーセント以内が目安★
・こう長（電線の長さ）が長いほど、電圧降下は大きくなる★
・電圧降下を抑えるには、電線を太くするか、配電電圧を高くする★
・需要率：設備容量に対する最大需要電力の割合。すべてが同時に使われることはない★
・不等率：各負荷の最大需要が同時に起こらないことを表す係数（1以上）★
・負荷率：平均需要電力を最大需要電力で除した値★

【計算例】需要率から最大需要電力を求める
