・無停電電源装置（UPS）は、瞬時に切り替わり、コンピュータの停止を防ぐ★
・蓄電池設備は、静かで即時に給電できるが容量に限りがある★
・自家発電設備の燃料は、必要な運転時間分を貯蔵する★

