　種類｜対象｜接地抵抗
　A種★｜高圧・特別高圧機器★｜10オーム以下★
　C種★｜300ボルト超の低圧機器★｜10オーム以下★
　D種★｜300ボルト以下の低圧機器★｜100オーム以下★
　⚠「D種接地工事の接地抵抗は10オーム以下」は誤り。100オーム以下★

