・合成樹脂管（PF管・CD管）配線：軽量で施工しやすい★
・CD管は自己消火性がなく、コンクリート埋設専用★
・PF管は自己消火性があり、露出配管や隠ぺい配管に使える★
・ケーブル工事：VVFケーブル（住宅で最も一般的）、CVケーブル★
・金属ダクト・バスダクト：大容量の幹線に用いる★
・フロアダクト・アンダーカーペット配線・フリーアクセスフロア：OA配線に用いる★
・フリーアクセスフロアは、レイアウト変更への対応性が最も高い★

【図解】配管・配線の使い分け
　方式｜特徴｜主な用途
　CD管★｜自己消火性なし★｜コンクリート埋設専用★
　PF管★｜自己消火性あり★｜露出・隠ぺい配管に可★
　フリーアクセスフロア★｜レイアウト変更に強い★｜事務所のOA配線★
　⚠「CD管は露出配管に用いることができる」は誤り

