・コンセントは家具の配置を想定して位置を決める★
・洗面所・厨房・屋外には接地極付きコンセントを設ける★
・3路スイッチを用いると、階段の上下など2か所から点滅できる★
・4路スイッチを併用すると、3か所以上からの点滅が可能★

